}

:root {
  --background: #fafafa;
  --foreground: #18181b;
  --muted: #f0f0f1;
  --muted-foreground: #71717a;
  --border: #e4e4e7;
}
.dark {
  --background: #101014;
  --foreground: #fafafa;
  --muted: #252529;
  --muted-foreground: #a1a1aa;
  --border: #303036;
  color-scheme: dark;
}
@layer base {
  * {
    border-color: var(--border);
  }
  body {
    margin: 0;
    background: var(--background);
    color: var(--foreground);
    font-family: Arial, Helvetica, sans-serif;
  }
  button,
  a {
    -webkit-tap-highlight-color: transparent;
  }
  button:not(:disabled),
  [role="button"] {
    cursor: pointer;
  }
  :focus-visible {
    outline: 2px solid #0088ff;
    outline-offset: 4px;
  }
}
.demo-action {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border-radius: 8px;
  background: var(--foreground);
  color: var(--background);
  padding: 10px 20px;
  font-size: 14px;
}
.demo-action:disabled {
  cursor: not-allowed;
  opacity: 0.4;
}
.section-example {
  min-height: 420px;
  width: 100%;
}
.section-example > section > div {
  min-height: 0;
  padding-top: 48px;
  padding-bottom: 48px;
}
.section-example h1 {
  font-size: 40px;
}
.section-example h2 {
  font-size: 30px;
}
.section-example p {
  text-wrap: pretty;
}
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
